define_constants;
clear; clc;

%% ==================== Load base case ====================
casefile = 'case22';
mpc = loadcase(casefile);

%% ==================== Apply parameter modifications ====================
% 1) Bus 8, QD: scale to 0
bus8 = find(mpc.bus(:, BUS_I) == 8);
if isempty(bus8)
    error('Bus 8 not found in case.');
end
mpc.bus(bus8, QD) = 0;

% 2) Generator at bus 1, QMIN: set to -50
g1 = find(mpc.gen(:, GEN_BUS) == 1);
if isempty(g1)
    error('No generator at bus 1 found in case.');
end
mpc.gen(g1, QMIN) = -50;

% 3) Branch (11 -> 19), BR_R: scale to 2
br_11_19 = find(mpc.branch(:, F_BUS) == 11 & mpc.branch(:, T_BUS) == 19);
if isempty(br_11_19)
    error('Branch (11->19) not found in case.');
end
mpc.branch(br_11_19, BR_R) = 2 * mpc.branch(br_11_19, BR_R);

% 4) Branch (22 -> 1), BR_B: scale to 1.1
br_22_1 = find(mpc.branch(:, F_BUS) == 22 & mpc.branch(:, T_BUS) == 1);
if isempty(br_22_1)
    error('Branch (22->1) not found in case.');
end
mpc.branch(br_22_1, BR_B) = 1.1 * mpc.branch(br_22_1, BR_B);

%% ==================== Solver / model options ====================
% MOST with DC model
mpopt = mpoption('most.dc_model', 1);
% tighter feasibility tolerance for OPF
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);
% keep MOST output reasonable (adjust as desired)
mpopt = mpoption(mpopt, 'verbose', 1, 'out.all', 0);

%% ==================== Build MOST multi-period data ====================
% xGen data (ramps/caps etc.)
% NOTE: these example files must exist on your MATLAB path.
% Replace with your own xGen/wind/profile definitions for case22 if needed.
xgd = loadxgendata('ex_xgd_ramp', mpc);

% Add wind and profiles (example-driven)
% ex_wind, ex_wind_profile_d, ex_load_profile must exist.
[iwind, mpc, xgd] = addwind(ex_wind, mpc, xgd);
profiles = getprofiles(ex_wind_profile_d, iwind);
profiles = getprofiles(ex_load_profile, profiles);
nt = size(profiles(1).values, 1);   % number of periods

% MOST data input
mdi = loadmd(mpc, nt, xgd, [], [], profiles);

%% ==================== Add phase angle difference penalty (DC, per period) ====================
% We add a quadratic cost on bus voltage angles Va in each period:
%   beta * ||E * Va||^2  where E maps Va to branch angle differences.
% MOST uses an OPF model for each period under the hood; we inject a user-defined
% quadratic cost into each period's OM via md.udata and MOST 'userfcn' hooks.
% For robustness across MATPOWER/MOST versions, we use MOST's userfcn callbacks.

beta = 10;

% Store data needed for the userfcn
ud.beta = beta;
ud.fbus = mpc.branch(:, F_BUS);
ud.tbus = mpc.branch(:, T_BUS);
ud.nb   = size(mpc.bus, 1);
ud.nl   = size(mpc.branch, 1);
mdi.userdata.angdiff_penalty = ud;

% Register MOST user function to add quadratic cost each period
% The callback signature follows MATPOWER/MOST conventions.
mdi = add_userfcn(mdi, 'most', 'formulation', @userfcn_angdiff_penalty_formulation);

%% ==================== Run MOST ====================
mdo = most(mdi, mpopt);

%% ==================== Results extraction ====================
EPg  = mdo.results.ExpectedDispatch;
Elam = mdo.results.GenPrices;

most_summary(mdo);

%% ==================== User function definitions ====================
function mdo = userfcn_angdiff_penalty_formulation(mdo)
% Add quadratic penalty beta * ||E*Va||^2 to each period model.
% Implemented as 0.5 * Va' * Q * Va with Q = 2*beta*(E'*E).

    define_constants;

    if ~isfield(mdo, 'mdi') || ~isfield(mdo.mdi, 'userdata') || ~isfield(mdo.mdi.userdata, 'angdiff_penalty')
        error('angdiff_penalty userdata not found.');
    end
    ud = mdo.mdi.userdata.angdiff_penalty;

    nb = ud.nb;
    nl = ud.nl;
    f  = ud.fbus;
    t  = ud.tbus;
    beta = ud.beta;

    % incidence-like matrix E such that (E*Va) = Va(from) - Va(to)
    E = sparse(1:nl, f,  1, nl, nb) + sparse(1:nl, t, -1, nl, nb);
    Q_va = 2 * beta * (E' * E);

    % For each time period, add quad cost on Va
    % MOST stores per-period OPF models in mdo.om (cell array) in many versions.
    % We handle both cell-array and struct variants.
    if iscell(mdo.om)
        for tt = 1:numel(mdo.om)
            mdo.om{tt} = mdo.om{tt}.add_quad_cost(sprintf('ang_diff_pen_t%03d', tt), Q_va, [], 0, {'Va'});
        end
    else
        % fallback: single OM (some MOST formulations)
        mdo.om = mdo.om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});
    end
end

define_constants;
clear; clc;

%% ==================== Load base case ====================
casefile = 'case22';
mpc0 = loadcase(casefile);

%% ==================== Apply parameter modifications ====================
mpc = mpc0;

% (1) Bus 8, QD: scale to 0
bus_id = 8;
bidx = find(mpc.bus(:, BUS_I) == bus_id);
if isempty(bidx)
    error('Bus %d not found in case.', bus_id);
end
mpc.bus(bidx, QD) = 0 * mpc.bus(bidx, QD);

% (2) Generator at bus 1, QMIN: set to -50
g_bus = 1;
gidx = find(mpc.gen(:, GEN_BUS) == g_bus);
if isempty(gidx)
    error('No generator found at bus %d.', g_bus);
end
% If multiple gens at bus 1, apply to all
mpc.gen(gidx, QMIN) = -50;

% (3) Branch (11->19), BR_R: scale to 2
fbus = 11; tbus = 19;
bridx = find(mpc.branch(:, F_BUS) == fbus & mpc.branch(:, T_BUS) == tbus);
if isempty(bridx)
    error('Branch %d -> %d not found.', fbus, tbus);
end
mpc.branch(bridx, BR_R) = 2 * mpc.branch(bridx, BR_R);

% (4) Branch (22->1), BR_B: scale to 1.1
fbus = 22; tbus = 1;
bridx = find(mpc.branch(:, F_BUS) == fbus & mpc.branch(:, T_BUS) == tbus);
if isempty(bridx)
    error('Branch %d -> %d not found.', fbus, tbus);
end
mpc.branch(bridx, BR_B) = 1.1 * mpc.branch(bridx, BR_B);

%% ==================== MOST multi-period setup (DC) ====================
% MOST options: DC model
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'most.dc_model', 1);

% Solver tolerance requirement
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ==================== Load xGenData and profiles ====================
% NOTE: These example data files must be available on the MATLAB path.
% You can replace them with your own xgendata/profiles consistent with case22.
try
    xgd = loadxgendata('ex_xgd_ramp', mpc);
catch
    error(['Could not load xGenData file ''ex_xgd_ramp''. ', ...
           'Please provide an xGenData ramp file compatible with case22 or update the filename.']);
end

% Add wind and profiles (example-based). If you do not want wind, remove this block
% and construct profiles only for load or other components.
try
    [iwind, mpc, xgd] = addwind(ex_wind, mpc, xgd);
    profiles = getprofiles(ex_wind_profile_d, iwind);
    profiles = getprofiles(ex_load_profile, profiles);
catch
    error(['Could not add wind/profiles (ex_wind, ex_wind_profile_d, ex_load_profile). ', ...
           'Please ensure these example structs are available, or replace with your own profiles.']);
end

nt = size(profiles(1).values, 1);   % number of periods

%% ==================== Build MOST data model ====================
mdi = loadmd(mpc, nt, xgd, [], [], profiles);

%% ==================== Add phase angle difference penalty each period ====================
% We implement: beta * ||E*Va||^2 per period, by adding a quadratic cost on Va
% with Q = 2*beta*(E'*E) to match MATPOWER's 0.5*x'*Q*x convention.
beta = 10;
nb = size(mpc.bus, 1);
nl = size(mpc.branch, 1);
f = mpc.branch(:, F_BUS);
t = mpc.branch(:, T_BUS);

% Map external bus numbers to internal indexing 1..nb used by MOST's internal model.
% Ensure bus numbering is consecutive in internal representation.
% Use ext2int to be safe.
mpc_int = ext2int(mpc);
% rebuild f,t with internal indices
f_int = mpc_int.branch(:, F_BUS);
t_int = mpc_int.branch(:, T_BUS);
nb_int = size(mpc_int.bus, 1);

E = sparse(1:nl, f_int,  1, nl, nb_int) + sparse(1:nl, t_int, -1, nl, nb_int);
Q_va = 2 * beta * (E' * E);

% MOST provides a way to add a custom quadratic cost via the md/om structure.
% We attach it as a user-defined quadratic cost on the Va variables in each period.
%
% Approach: create a MOST user-defined cost structure for each time period.
% MOST's internal OM is created during solve, so we pass user costs via mdi.

% Initialize user-defined costs container if missing
if ~isfield(mdi, 'uc') || isempty(mdi.uc)
    mdi.uc = struct();
end

% Add quadratic cost on Va for each period.
% MOST supports uc.cost with fields: type, idx, name, N, H, Cw, fparm, cr, k, vs, etc.
% The most robust way without relying on undocumented fields is to use the
% userfcn mechanism that hooks into the OPF model after it is built.

% Define a userfcn to add quadratic cost on Va for each period
mdi.userfcn = {
    'most', 'formulation', @userfcn_most_add_angdiff_cost, struct('Qva', Q_va)
};

%% ==================== Solve with MOST ====================
mdo = most(mdi, mpopt);

%% ==================== Extract results ====================
EPg  = mdo.results.ExpectedDispatch;   % expected dispatch (multi-period)
Elam = mdo.results.GenPrices;         % LMPs / prices

most_summary(mdo);

%% ==================== User function (nested / local) ====================
function om = userfcn_most_add_angdiff_cost(om, md, mpopt, args)
% Adds quadratic cost: 0.5 * Va' * Qva * Va in each period
% where Qva = 2*beta*(E'*E), so equals beta*||E*Va||^2.

    Qva = args.Qva;

    % Determine number of periods from md
    nt = md.idx.nt;

    % Add to each time period's OPF model
    for t = 1:nt
        omt = om(t);
        % Va variable set exists in DC model
        omt = omt.add_quad_cost(sprintf('ang_diff_pen_t%03d', t), Qva, [], 0, {'Va'});
        om(t) = omt;
    end
end

clear; clc;
define_constants;

%% ==================== Load base case ====================
mpc0 = loadcase('case22');
if isempty(mpc0)
    error('Failed to load case22');
end

%% ==================== Apply parameter modifications ====================
mpc = mpc0;

% (1) Bus 8, QD: scale to 0
b8 = find(mpc.bus(:, BUS_I) == 8);
if isempty(b8)
    error('Bus 8 not found in case22');
end
mpc.bus(b8, QD) = 0;

% (2) Generator at bus 1, QMIN: set to -50
g1 = find(mpc.gen(:, GEN_BUS) == 1);
if isempty(g1)
    error('No generator found at bus 1 in case22');
end
mpc.gen(g1(1), QMIN) = -50;

% (3) Branch (11->19), BR_R: scale to 2
br_1119 = find(mpc.branch(:, F_BUS) == 11 & mpc.branch(:, T_BUS) == 19);
if isempty(br_1119)
    error('Branch 11->19 not found in case22');
end
mpc.branch(br_1119(1), BR_R) = 2 * mpc.branch(br_1119(1), BR_R);

% (4) Branch (22->1), BR_B: scale to 1.1
br_221 = find(mpc.branch(:, F_BUS) == 22 & mpc.branch(:, T_BUS) == 1);
if isempty(br_221)
    error('Branch 22->1 not found in case22');
end
mpc.branch(br_221(1), BR_B) = 1.1 * mpc.branch(br_221(1), BR_B);

%% ==================== Add load shedding as synthetic generators ====================
nb = size(mpc.bus, 1);
ng0 = size(mpc.gen, 1);

load_buses = find(mpc.bus(:, PD) > 0);
nl_load = length(load_buses);

ncol_gen = size(mpc.gen, 2);
new_gen = zeros(nl_load, ncol_gen);

for k = 1:nl_load
    b = load_buses(k);
    Pd_k = mpc.bus(b, PD);

    g = mpc.gen(1, :);      % template to preserve column compatibility
    g(GEN_BUS)    = mpc.bus(b, BUS_I);
    g(PG)         = 0;
    g(QG)         = 0;
    g(QMAX)       = 0;
    g(QMIN)       = 0;
    g(VG)         = 1.0;
    g(GEN_STATUS) = 1;
    g(PMAX)       = Pd_k;
    g(PMIN)       = 0;

    new_gen(k, :) = g;
end

mpc.gen = [mpc.gen; new_gen];
ng = size(mpc.gen, 1);
shed_gen_idx = (ng0+1:ng)';

% Add gencost rows for shedding generators
ncol_gc = size(mpc.gencost, 2);
old_cost = mpc.gencost;

% polynomial cost: [2 0 0 3 c2 c1 c0]
p_cost = 100  * ones(nl_load, 1);
q_cost = 1000 * ones(nl_load, 1);
r_cost = 5000 * ones(nl_load, 1);

new_cost = zeros(nl_load, ncol_gc);
new_cost(:, 1) = 2;  % MODEL
new_cost(:, 2) = 0;  % STARTUP
new_cost(:, 3) = 0;  % SHUTDOWN
new_cost(:, 4) = 3;  % NCOST
new_cost(:, 5) = r_cost;
new_cost(:, 6) = q_cost;
new_cost(:, 7) = p_cost;

mpc.gencost = [old_cost; new_cost];

%% ==================== Options ====================
mpopt = mpoption('verbose', 1, 'out.all', 0);
mpopt = mpoption(mpopt, 'model', 'AC');
mpopt = mpoption(mpopt, 'opf.ac.solver', 'MIPS');
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ==================== Build L-index ingredients (using external indexing mpc) ====================
lambda_L = 1.0;

[Ybus, ~, ~] = makeYbus(mpc.baseMVA, mpc.bus, mpc.branch);

bus_type = mpc.bus(:, BUS_TYPE);
idxG = find(bus_type == REF | bus_type == PV);
idxL = find(bus_type == PQ);

if isempty(idxL)
    error('No PQ buses found; L-index not defined.');
end

Y_LL = Ybus(idxL, idxL);
Y_LG = Ybus(idxL, idxG);
Fmat = -(Y_LL \ Y_LG);

%% ==================== Convert to internal indexing for OPF model & security constraints ====================
mpc_int = ext2int(mpc);
baseMVA = mpc_int.baseMVA;
bus = mpc_int.bus;
branch = mpc_int.branch;

nb_int = size(bus, 1);
nl_int = size(branch, 1);

%% ==================== Build PTDF/LODF for DC N-1 constraints (internal) ====================
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);
cont_set = find(in_service & has_limit);
nc = length(cont_set);

if isempty(cont_set)
    error('Contingency set is empty: no in-service branches with RATE_A > 0.');
end

constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);
rateA = branch(:, RATE_A);

%% ==================== OPF model setup (AC) ====================
om = opf_setup(mpc_int, mpopt);

idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
nv = om.var.N;

iVa1 = idx_i1.Va;
iVaN = idx_iN.Va;

%% ==================== Add N-1 linear constraints on Va ====================
% For each contingency k (line outage), enforce monitored line flows within +/-RATE_A.

nRows = 2 * nL * nc;
A = spalloc(nRows, nv, min(nRows * nb_int, 2 * nL * nc * max(1, ceil(nb_int/4))));
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);    % nl_int x 1
    Bf_row_k = Bf(k, :);      % 1 x nb_int
    Pk       = Pfinj(k);

    % Post-contingency linear flow model
    Bf_k = Bf + lodf_col * Bf_row_k;   % nl_int x nb_int
    Pf_k = Pfinj + lodf_col * Pk;      % nl_int x 1

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);
        cst = Pf_k(ell);

        % Upper bound:  aVa*Va <= limit - cst
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % Lower bound: -aVa*Va <= limit + cst   (i.e., aVa*Va >= -limit - cst)
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch when building N-1 constraints.');
end

om.add_lin_constraint('N1_branch_limits_dc_approx', A, l, u);

%% ==================== Add L-index nonlinear cost (finite-difference gradient) ====================
% Note: idxG/idxL and Fmat were computed on the *external* bus ordering.
% We must map internal solution back to external ordering inside the cost.
% Use the internal->external permutation stored in mpc_int.order.

% Build mapping vectors for buses (internal index -> external bus row index)
% i2e gives external BUS_I numbers; we also need row positions in external bus matrix.
i2e_busnum = mpc_int.order.bus.i2e;          % internal bus index -> external bus index (row in ext bus)
% Here, because ext2int preserves bus row order but removes out-of-service, i2e maps to ext row indices.

fcn = @(x) l_index_cost_fcn_int(x, lambda_L, idx_i1, idx_iN, nv, Fmat, idxG, idxL, i2e_busnum);
om.add_nln_cost('L_index_cost', 1, fcn);

%% ==================== Solve ====================
[x, f, eflag, output, lambda] = om.solve();

if eflag <= 0
    error('SC-ACOPF failed. Exit flag: %d', eflag);
end

%% ==================== Build results (internal -> external) ====================
results_int = mpc_int;
results_int.f = f;
results_int.success = (eflag > 0);
results_int.eflag = eflag;
results_int.output = output;
results_int.lambda = lambda;

% Fill primal solution into results_int
Va = x(idx_i1.Va:idx_iN.Va);
Vm = x(idx_i1.Vm:idx_iN.Vm);
Pg = x(idx_i1.Pg:idx_iN.Pg);
Qg = x(idx_i1.Qg:idx_iN.Qg);

results_int.bus(:, VA) = Va * 180/pi;
results_int.bus(:, VM) = Vm;
results_int.gen(:, PG) = Pg;
results_int.gen(:, QG) = Qg;

results = int2ext(results_int);

%% ==================== Post-processing: load shedding summary (external) ====================
% shed_gen_idx was built on external mpc indexing; after ext2int/int2ext, generator ordering is preserved.
Pg_all = results.gen(:, PG);
Lshd = Pg_all(shed_gen_idx);
orig_load = mpc.bus(load_buses, PD);
remain_load = orig_load - Lshd;

total_orig = sum(orig_load);
total_shed = sum(Lshd);

shed_cost = sum(p_cost + q_cost .* Lshd + r_cost .* (Lshd.^2));

%% ==================== Post-processing: compute L-index on external solution ====================
Va_ext = results.bus(:, VA) * pi/180;
Vm_ext = results.bus(:, VM);
V = Vm_ext .* exp(1j * Va_ext);
V_G = V(idxG);
V_L = V(idxL);
T = Fmat * V_G;
U = T ./ V_L;
Lvec = abs(1 - U);
Lmax = max(Lvec);

fprintf('\n=== SC-ACOPF (case22) with Load Shedding + L-index cost + DC N-1 constraints ===\n');
fprintf('Converged: %d\n', results.success);
fprintf('Objective (total) = %.6f\n', results.f);
fprintf('Total original load  = %.3f MW\n', total_orig);
fprintf('Total shed load      = %.3f MW\n', total_shed);
fprintf('Shed ratio           = %.2f %%\n', 100*total_shed/max(1e-9,total_orig));
fprintf('Shedding cost term   = %.6f\n', shed_cost);
fprintf('L_max                = %.6f\n', Lmax);

fprintf('\nBus  OrigLoad  ShedLoad  RemainLoad  ShedRatio(%%)\n');
for k = 1:nl_load
    b = mpc.bus(load_buses(k), BUS_I);
    if orig_load(k) > 1e-9
        sr = 100 * Lshd(k) / orig_load(k);
    else
        sr = 0;
    end
    fprintf('%3d  %8.3f  %8.3f  %10.3f   %8.2f\n', b, orig_load(k), Lshd(k), remain_load(k), sr);
end

% attach for convenience
results.L_index = Lvec;
results.L_max = Lmax;

%% ==================== Nonlinear cost helper ====================
function [f, df, d2f] = l_index_cost_fcn_int(x, lambda_L, idx_i1, idx_iN, nv, Fmat, idxG_extrows, idxL_extrows, i2e_busrow)
% Nonlinear cost: lambda_L * max_j L_j, computed on external bus ordering.
% x is the OPF decision vector for the INTERNAL model; Va/Vm blocks correspond to internal bus order.
% i2e_busrow maps internal bus index -> external bus row index.

    Va_int = x(idx_i1.Va:idx_iN.Va);
    Vm_int = x(idx_i1.Vm:idx_iN.Vm);

    % map internal voltage vectors to external row positions
    nb_int = length(Va_int);
    nb_ext = max(i2e_busrow);
    Va_ext = zeros(nb_ext, 1);
    Vm_ext = zeros(nb_ext, 1);

    for ii = 1:nb_int
        erow = i2e_busrow(ii);
        Va_ext(erow) = Va_int(ii);
        Vm_ext(erow) = Vm_int(ii);
    end

    V = Vm_ext .* exp(1j * Va_ext);
    V_G = V(idxG_extrows);
    V_L = V(idxL_extrows);

    T = Fmat * V_G;
    U = T ./ V_L;
    Lvec = abs(1 - U);
    Lmax = max(Lvec);

    f = lambda_L * Lmax;

    if nargout > 1
        eps_fd = 1e-7;
        df = zeros(nv, 1);
        for k = 1:nv
            x_plus = x;
            x_plus(k) = x_plus(k) + eps_fd;
            f_plus = l_index_cost_fcn_int(x_plus, lambda_L, idx_i1, idx_iN, nv, Fmat, idxG_extrows, idxL_extrows, i2e_busrow);
            df(k) = (f_plus - f) / eps_fd;
        end
    end

    if nargout > 2
        d2f = sparse(nv, nv);
    end
end

define_constants;
clearvars -except mpopt; clc;

%% ==================== User Settings ====================
CASE_NAME = 'case118';
SOLVER = 'MIPS';
VERBOSE_LEVEL = 1;
SUPPRESS_OUTPUT = 0;
OPF_VIOLATION = 1e-6;

%% ==================== Load Case ====================
mpc0 = loadcase(CASE_NAME);
if isempty(mpc0)
    error('Failed to load case: %s', CASE_NAME);
end

%% ==================== Parameter Modifications (Base Spec) ====================
% Bus 78, BS set to -0.1
bus78 = find(mpc0.bus(:, BUS_I) == 78);
if isempty(bus78)
    error('Bus 78 not found in %s.', CASE_NAME);
end
mpc0.bus(bus78, BS) = -0.1;

%% ==================== MP Options ====================
mpopt = mpoption('verbose', VERBOSE_LEVEL, 'out.all', SUPPRESS_OUTPUT);
mpopt = mpoption(mpopt, 'model', 'DC');
mpopt = mpoption(mpopt, 'opf.dc.solver', SOLVER);
mpopt = mpoption(mpopt, 'opf.violation', OPF_VIOLATION);

%% ==================== Build DC-SCOPF Model (LODF-based) ====================
% Use internal indexing for consistent PTDF/LODF and OPF model matrices
mpc = ext2int(mpc0);
baseMVA = mpc.baseMVA;
bus    = mpc.bus;
branch = mpc.branch;

nb = size(bus, 1);
nl = size(branch, 1);

% Build DC matrices and sensitivity factors
% Bf: maps bus angles Va to branch flows (in MW on system baseMVA)
% Pfinj: constant term in branch flow equations
[~, Bf, ~, Pfinj] = makeBdc(baseMVA, bus, branch);
PTDF = makePTDF(baseMVA, bus, branch);
LODF = makeLODF(branch, PTDF);

% Contingency set: in-service branches with a positive RATE_A
in_service = (branch(:, BR_STATUS) == 1);
has_limit  = (branch(:, RATE_A) > 0);
cont_set   = find(in_service & has_limit);
nc = length(cont_set);
if nc == 0
    error('Contingency set is empty: no in-service branches with RATE_A > 0.');
end

% Monitored set (constraints applied to these lines)
constrain_lines = find(in_service & has_limit);
nL = length(constrain_lines);
if nL == 0
    error('No monitored lines found: no in-service branches with RATE_A > 0.');
end
rateA = branch(:, RATE_A);

% Set up OPF model (DC OPF)
om = opf_setup(mpc, mpopt);
nv = om.var.N;

% Indices of Va variables in the full decision vector
iVa1 = om.var.idx.i1.Va;
iVaN = om.var.idx.iN.Va;

% Build linear constraints for all contingencies and monitored lines:
% For each outage k, post-contingency flow on line ell:
%   f_ell^(k) = (Bf + LODF(:,k)*Bf(k,:))(ell,:)*Va + (Pfinj + LODF(:,k)*Pfinj(k))(ell)
% Enforce: -RATE_A(ell) <= f_ell^(k) <= RATE_A(ell)

nRows = 2 * nL * nc;

% Each row only touches Va variables; allocate sparse A accordingly
A = spalloc(nRows, nv, nRows * nb);
l = -inf(nRows, 1);
u =  inf(nRows, 1);

row = 0;
for kk = 1:nc
    k = cont_set(kk);

    lodf_col = LODF(:, k);     % nl x 1
    Bf_row_k = Bf(k, :);       % 1 x nb
    Pk       = Pfinj(k);       % scalar

    % Post-contingency flow mapping (all lines) under outage of line k
    Bf_k = Bf + lodf_col * Bf_row_k;   % nl x nb
    Pf_k = Pfinj + lodf_col * Pk;      % nl x 1

    for ii = 1:nL
        ell = constrain_lines(ii);
        limit = rateA(ell);

        aVa = Bf_k(ell, :);
        cst = Pf_k(ell);

        % Upper bound: aVa*Va + cst <= limit  -> aVa*Va <= limit - cst
        row = row + 1;
        A(row, iVa1:iVaN) = aVa;
        u(row) = limit - cst;

        % Lower bound: aVa*Va + cst >= -limit -> -(aVa*Va) <= limit + cst
        row = row + 1;
        A(row, iVa1:iVaN) = -aVa;
        u(row) = limit + cst;
    end
end

if row ~= nRows
    error('Row count mismatch while building N-1 constraints: got %d, expected %d.', row, nRows);
end

% Add N-1 security constraints to OPF model
om.add_lin_constraint('N1_branch_limits', A, l, u);

%% ==================== Solve ====================
[x, f, eflag, output, lambda] = om.solve();
if eflag <= 0
    error('DC-SCOPF failed. Exit flag: %d', eflag);
end

%% ==================== Collect Results ====================
idx_i1 = om.var.idx.i1;
idx_iN = om.var.idx.iN;
Va_solution = x(idx_i1.Va:idx_iN.Va);
Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

results = mpc;
results.bus(:, VA)  = Va_solution * 180/pi;  % radians to degrees
results.gen(:, PG)  = Pg_solution;
results.f           = f;
results.success     = (eflag > 0);
results.eflag       = eflag;
results.output      = output;
results.lambda      = lambda;

% Convert back to external indexing for reporting
results = int2ext(results);

fprintf('\n=== DC-SCOPF Completed (case118) ===\n');
fprintf('Objective value: %.6f\n', f);
if isfield(output, 'alg')
    fprintf('Solver: %s\n', output.alg);
end
if isfield(output, 'iterations')
    fprintf('Iterations: %d\n', output.iterations);
end

fprintf('\nGenerator PG (MW):\n');
disp(results.gen(:, PG));

fprintf('\nBus Voltage Angles VA (deg):\n');
disp(results.bus(:, VA));

define_constants;

%% ===================== User options =====================
useropt = struct();
useropt.casename   = 'case51ga';
useropt.model      = 'DC';
useropt.solver     = 'OT';      % template indicates DC with OT
useropt.M          = 1e5;       % big-M
useropt.GUB        = 4;         % max number of opened lines
useropt.heuristic  = 'basic';
useropt.MaxTime    = 600;
useropt.MaxNodes   = 5e5;

%% ===================== Load case & base options =====================
mpc0 = loadcase(useropt.casename);

% solver / model options
mpopt = mpoption('model', useropt.model, 'verbose', 2, 'out.all', 0);
mpopt = mpoption(mpopt, 'opf.dc.solver', useropt.solver);
mpopt = mpoption(mpopt, 'opf.violation', 1e-6);

%% ===================== Parameter modifications =====================
mpc = mpc0;

% --- generator at bus 8 cost scaling ---
% Find all generators at bus 8 (typically one)
g8 = find(mpc.gen(:, GEN_BUS) == 8);
if isempty(g8)
    error('No generator found at bus 8.');
end

% Ensure gencost exists and is polynomial
if ~isfield(mpc, 'gencost') || isempty(mpc.gencost)
    error('mpc.gencost is missing/empty.');
end

for k = 1:length(g8)
    gi = g8(k);
    if mpc.gencost(gi, MODEL) ~= POLYNOMIAL
        error('Generator cost at bus 8 is not polynomial; scaling template assumes polynomial costs.');
    end
    ncost = mpc.gencost(gi, NCOST);
    % polynomial coefficients are in the last NCOST columns
    % For quadratic: [c2 c1 c0] corresponds to COST_PARAMS_C3, C2, C1 in the prompt naming
    % Here we interpret:
    %   COST_PARAMS_C3 = quadratic coefficient (c2)
    %   COST_PARAMS_C1 = constant term (c0)
    % If NCOST < 3, adjust accordingly.
    coeff_cols = (size(mpc.gencost,2)-ncost+1) : size(mpc.gencost,2);
    coeff = mpc.gencost(gi, coeff_cols);

    if ncost >= 3
        % c2 c1 c0
        coeff(1) = coeff(1) * 1.0;  % COST_PARAMS_C3 scale to 1
        coeff(end) = coeff(end) * 1.1; % COST_PARAMS_C1 scale to 1.1
    elseif ncost == 2
        % linear: c1 c0 (no quadratic)
        % apply the COST_PARAMS_C1 scaling to constant term only
        coeff(end) = coeff(end) * 1.1;
    elseif ncost == 1
        % constant only
        coeff(end) = coeff(end) * 1.1;
    end

    mpc.gencost(gi, coeff_cols) = coeff;
end

% --- Branch (5->14) BR_STATUS set to 1 ---
f = mpc.branch(:, F_BUS);
t = mpc.branch(:, T_BUS);
idx_514 = find(f == 5 & t == 14);
if isempty(idx_514)
    warning('Branch (5->14) not found in case. No status change applied.');
else
    mpc.branch(idx_514, BR_STATUS) = 1;
end

% --- Branch (43->5) BR_X scale by 1.2 ---
idx_435 = find(f == 43 & t == 5);
if isempty(idx_435)
    warning('Branch (43->5) not found in case. No BR_X scaling applied.');
else
    mpc.branch(idx_435, BR_X) = 1.2 * mpc.branch(idx_435, BR_X);
end

%% ===================== Build OTS OPF model =====================
% Convert to internal indexing
mpc = ext2int(mpc, mpopt);

% Setup OPF model
om = opf_setup(mpc, mpopt);

[baseMVA, bus, gen, branch] = deal(mpc.baseMVA, mpc.bus, mpc.gen, mpc.branch);
[nb, ng, nl] = deal(size(bus,1), size(gen,1), size(branch,1));

% Relax/replace original Pmis constraints bounds (as in template)
np = om.getN('lin','Pmis');
if np > 0
    om.set_params('lin', 'Pmis', {'l', 'u'}, {-Inf(np,1), Inf(np,1)});
end

% Add OTS variables: Pf (continuous) and Z (binary)
om.add_var('Pf', nl, zeros(nl,1));
om.add_var('Z',  nl, ones(nl,1), zeros(nl,1), ones(nl,1), 'B');

% Add reserve variables (continuous)
Ru_min = zeros(ng, 1);
Rd_min = zeros(ng, 1);
Rs_min = zeros(ng, 1);
Rn_min = zeros(ng, 1);

Ru_max = gen(:, PMAX);
Rd_max = gen(:, PMAX);
Rs_max = gen(:, PMAX);
Rn_max = gen(:, PMAX);

om.add_var('Ru', ng, Ru_min, Ru_max);
om.add_var('Rd', ng, Rd_min, Rd_max);
om.add_var('Rs', ng, Rs_min, Rs_max);
om.add_var('Rn', ng, Rn_min, Rn_max);

%% --------------------- Network matrices ---------------------
[B, Bf, Pbusinj, Pfinj] = makeBdc(baseMVA, bus, branch);
fb = branch(:, F_BUS);
tb = branch(:, T_BUS);

Cft = sparse([(1:nl)'; (1:nl)'], [fb; tb], [ones(nl,1); -ones(nl,1)], nl, nb);
Cg  = sparse(gen(:, GEN_BUS), (1:ng)', ones(ng,1), nb, ng);

% Power balance in terms of Pf and Pg: Cft' * Pf - Cg*Pg = -(Pd+Gs)/base - Pbusinj
A_pmis = [Cft', -Cg];
b_pmis = -(bus(:, PD) + bus(:, GS)) / baseMVA - Pbusinj;
om.add_lin_constraint('Pfmis', A_pmis, b_pmis, b_pmis, {'Pf','Pg'});

%% --------------------- Branch thermal limits with Z ---------------------
Il = speye(nl);

% determine per-branch Pmax/Pmin in p.u. adjusted by phase shift injections
il = find(branch(:, RATE_A) ~= 0 & branch(:, RATE_A) < 1e10);
Pmax = inf(nl,1);
Pmin = inf(nl,1);
if ~isempty(il)
    Pmax(il) = branch(il, RATE_A) / baseMVA - Pfinj(il);
    Pmin(il) = branch(il, RATE_A) / baseMVA + Pfinj(il);
end

% Pf <=  Pmax .* Z  => Pf - diag(Pmax)*Z <= 0
% Pf >= -Pmin .* Z  => Pf + diag(Pmin)*Z >= 0  (note: Pmin is positive bound term)
om.add_lin_constraint('Pfu', [Il, -spdiags(Pmax, 0, nl, nl)], [], zeros(nl,1), {'Pf','Z'});
om.add_lin_constraint('Pfl', [Il,  spdiags(Pmin, 0, nl, nl)], zeros(nl,1), [], {'Pf','Z'});

%% --------------------- Big-M DC flow linking ---------------------
% -M*1 <= (Bf*Va - Pf) - M*Z <= +M*1  (rearranged to match template)
% Template form:
%   Ml: [Bf, -I, -M*I] * [Va; Pf; Z] >= -M*1
%   Mu: [Bf, -I, +M*I] * [Va; Pf; Z] <= +M*1
rhs = useropt.M * ones(nl,1);
om.add_lin_constraint('Ml', [Bf, -Il, -useropt.M*Il], -rhs, [], {'Va','Pf','Z'});
om.add_lin_constraint('Mu', [Bf, -Il,  useropt.M*Il], [],  rhs, {'Va','Pf','Z'});

%% --------------------- Switching budget (GUB) ---------------------
% At most GUB lines can be opened: sum(Z) >= nl - GUB
om.add_lin_constraint('GUB', ones(1, nl), nl - useropt.GUB, [], {'Z'});

%% ===================== Reserve constraints =====================
% Need current variable indexing
nv  = om.var.N;
idx = om.var.idx;
i1  = idx.i1;
iN  = idx.iN;

pg_idx = i1.Pg:iN.Pg;
ru_idx = i1.Ru:iN.Ru;
rd_idx = i1.Rd:iN.Rd;
rs_idx = i1.Rs:iN.Rs;
rn_idx = i1.Rn:iN.Rn;

% 1) Upward headroom: Pg + Ru + Rs + Rn <= PMAX
A_upcap = sparse(ng, nv);
for i = 1:ng
    A_upcap(i, pg_idx(i)) = 1;
    A_upcap(i, ru_idx(i)) = 1;
    A_upcap(i, rs_idx(i)) = 1;
    A_upcap(i, rn_idx(i)) = 1;
end
om.add_lin_constraint('cap_up', A_upcap, [], gen(:, PMAX));

% 2) Downward capability: Pg - Rd >= PMIN
A_downcap = sparse(ng, nv);
for i = 1:ng
    A_downcap(i, pg_idx(i)) = 1;
    A_downcap(i, rd_idx(i)) = -1;
end
om.add_lin_constraint('cap_down', A_downcap, gen(:, PMIN), inf(ng,1));

% Reserve requirements: each >= 1% total load
total_load = sum(bus(:, PD));  % MW
R_up_req   = 0.01 * total_load;
R_down_req = 0.01 * total_load;
R_spin_req = 0.01 * total_load;
R_non_req  = 0.01 * total_load;

A_Ru = sparse(1, nv); A_Ru(ru_idx) = 1;
A_Rd = sparse(1, nv); A_Rd(rd_idx) = 1;
A_Rs = sparse(1, nv); A_Rs(rs_idx) = 1;
A_Rn = sparse(1, nv); A_Rn(rn_idx) = 1;

om.add_lin_constraint('req_Ru', A_Ru, R_up_req,   inf);
om.add_lin_constraint('req_Rd', A_Rd, R_down_req, inf);
om.add_lin_constraint('req_Rs', A_Rs, R_spin_req, inf);
om.add_lin_constraint('req_Rn', A_Rn, R_non_req,  inf);

%% ===================== Reserve cost added to objective =====================
% Linear reserve procurement cost
c_u = 3; c_d = 2; c_s = 5; c_n = 1;

c = zeros(nv, 1);
c(ru_idx) = c_u;
c(rd_idx) = c_d;
c(rs_idx) = c_s;
c(rn_idx) = c_n;

Q = sparse(nv, nv);
om.add_quad_cost('reserve_cost', Q, c, 0);

%% ===================== Solve MILP =====================
opt = mpopt2qpopt(mpopt, om.problem_type());
if ~isfield(opt, 'intlinprog_opt')
    opt.intlinprog_opt = struct();
end
opt.intlinprog_opt.MaxTime   = useropt.MaxTime;
opt.intlinprog_opt.MaxNodes  = useropt.MaxNodes;
opt.intlinprog_opt.Heuristics = useropt.heuristic;

[x, f, eflag, output, lambda] = om.solve(opt);

%% ===================== Map results back =====================
results = int2ext(mpc);
results.success = (eflag > 0);
results.f = f;

if eflag <= 0
    fprintf('DC-OTS with reserves did not converge/solve (eflag=%d).\n', eflag);
else
    % Extract internal solution pieces
    Pg = x(pg_idx);
    Ru = x(ru_idx);
    Rd = x(rd_idx);
    Rs = x(rs_idx);
    Rn = x(rn_idx);

    % write back generator dispatch (internal indexing)
    results = ext2int(results, mpopt); % back to internal to assign consistently
    results.gen(:, PG) = Pg;
    results = int2ext(results);

    fprintf('\n===== DC-OTS with Reserves (case51ga) =====\n');
    fprintf('Objective (gen cost + reserve costs) = %.6f\n', f);
    fprintf('Total reserves: sum(Ru)=%.3f, sum(Rd)=%.3f, sum(Rs)=%.3f, sum(Rn)=%.3f (MW)\n', ...
        sum(Ru), sum(Rd), sum(Rs), sum(Rn));
end
